# ── Couleurs du thème bleu-vert ───────────────────────────────────────────

SCORE_HIGH = "#2A8A4A"
SCORE_MED = "#8A7A2A"
SCORE_LOW = "#8A2A2A"
ACCENT_BLUE = "#1A6A9A"
ACCENT_BLUE_LIGHT = "#2A7FBF"
BG_DARK = "#0A0E14"
BG_PANEL = "#0C1018"
BG_SIDEBAR = "#0D1318"
BORDER_COLOR = "#1A2332"
TEXT_PRIMARY = "#E8EAF0"
TEXT_SECONDARY = "#4A6080"
TEXT_MUTED = "#3D5266"
TEXT_DIM = "#2D4052"


# ══════════════════════════════════════════════════════════════════════════
