        data = {
            "key_cache": MockMXArray(128, "float16", 4, (8, 4, 256, 128)),
            "value_cache": MockMXArray(128, "float16", 4, (8, 4, 256, 128)),
        }
        result = window_kv_cache(data, max_tokens=128, system_prompt_tokens=32)
