    passed = 0
    for test in tests:
        try:
            test()
            passed += 1
        except Exception as e:
            print(f"  \u274c {test.__name__}: {e}")
    
    total = len(tests)
    print(f"\n{'=' * 40}")
    print(f"Sprint 1 \u2014 {passed}/{total} tests OK \u2705" if passed == total else
          f"Sprint 1 \u2014 {passed}/{total} tests, {total-passed} ECHEC \u274c")


