    assert bubble._mode == "CLOUD", f"mode attendu 'CLOUD', eu {bubble._mode!r}"
    assert bubble._model_name == "Groq llama-3.3", (
        f"model_name attendu 'Groq llama-3.3', eu {bubble._model_name!r}"
    )
